INSERT INTO quote (phrase) VALUES ('«Успех — это способность шагать от одной неудачи к другой, не теряя энтузиазма.» — Уинстон Черчилль');
INSERT INTO quote (phrase) VALUES ('«Не пиши код, который работает. Пиши код, который можно читать.»');
INSERT INTO quote (phrase) VALUES ('«Ваше время ограничено, не тратьте его, живя чужой жизнью.» — Стив Джобс');
INSERT INTO quote (phrase) VALUES ('«Секрет успеха — перестать говорить и начать делать.» — Уолт Дисней');
INSERT INTO quote (phrase) VALUES ('«Искусственный интеллект не заменит разработчиков. Разработчики, использующие ИИ, заменят тех, кто им не пользуется.»');
INSERT INTO quote (phrase) VALUES ('«Жизнь — это то, что происходит с тобой, пока ты оживлённо строишь другие планы.» — Джон Леннон');
INSERT INTO quote (phrase) VALUES ('«Если тебе тяжело, значит ты поднимаешься в гору. Если легко — летишь в пропасть.» — Генри Форд');
INSERT INTO quote (phrase) VALUES ('«Логика проведёт вас от А до Я. Воображение доставит вас куда угодно.» — Альберт Эйнштейн');
INSERT INTO quote (phrase) VALUES ('«Любой дурак может написать код, понятный компьютеру. Хорошие программисты пишут код, понятный людям.» — Мартин Фаулер');
INSERT INTO quote (phrase) VALUES ('«Сложнее всего начать действовать. Все остальное зависит только от упорства.» — Амелия Эрхарт');
INSERT INTO quote (phrase) VALUES ('«Тот, кто не рискует, в конечном счёте рискует в 100 раз больше.» — Марк Цукерберг');
INSERT INTO quote (phrase) VALUES ('«Успех обычно приходит к тем, кто слишком занят, чтобы его искать.» — Генри Дэвид Торо');
INSERT INTO quote (phrase) VALUES ('«Работа над хорошим кодом как создание хорошей прозы: вам нужен черновик, который вы потом доведёте до ума к релизу.»');
INSERT INTO quote (phrase) VALUES ('«Неудача — это просто возможность начать снова, но уже более мудро.» — Генри Форд');
INSERT INTO quote (phrase) VALUES ('«Безумие: делать одно и то же снова и снова, ожидая разных результатов.» — Альберт Эйнштейн');
INSERT INTO quote (phrase) VALUES ('«В жизни есть только две настоящие трагедии: одна — когда не получаешь того, чего хочешь, а вторая — когда получаешь.» — Оскар Уайльд');
INSERT INTO quote (phrase) VALUES ('«Обожаю дедлайны. Мне нравится тот свистящий звук, с которым они проносятся мимо.» — Дуглас Адамс');
INSERT INTO quote (phrase) VALUES ('«Мой доктор сказал мне прекратить устраивать ужины для четырех персон. Если честно, я даже не знал, что это вредно: я всегда ем один.» — Орсон Уэллс');
INSERT INTO quote (phrase) VALUES ('«Лень — это привычка отдыхать до того, как ты устанешь.» — Жюль Ренар');
INSERT INTO quote (phrase) VALUES ('«Никогда не откладывай на завтра то, что можешь сделать послезавтра.» — Марк Твен');
INSERT INTO quote (phrase) VALUES ('«Нельзя верить всему, что читаешь в интернете.» — Владимир Ильич Ленин');
INSERT INTO quote (phrase) VALUES ('«Даже если вы на правильном пути, вас всё равно задавят, если вы будете просто сидеть на нём.» — Уилл Роджерс');
INSERT INTO quote (phrase) VALUES ('«Всегда одалживайте деньги у пессимиста. Он все равно не ждет, что вы их вернете.» — Оскар Уайльд');
INSERT INTO quote (phrase) VALUES ('«Программирование — это как секс: одна ошибка, и вам придётся поддерживать её всю жизнь.» — Майкл Синц');
INSERT INTO quote (phrase) VALUES ('«Дебаггинг — это как быть детективом в криминальном фильме, где ты одновременно являешься и убийцей.» — Филипе Фортес');
INSERT INTO quote (phrase) VALUES ('«Я не провалил тест. Я просто нашел 100 способов сделать его неправильно.» — Бенджамин Франклин');
INSERT INTO quote (phrase) VALUES ('«Чтобы понять рекурсию, сначала нужно понять рекурсию.»');
INSERT INTO quote (phrase) VALUES ('«Многозадачность — это искусство портить несколько вещей одновременно.»');
INSERT INTO quote (phrase) VALUES ('«Первое правило программирования: "Если оно работает — не трогай!"»');
INSERT INTO quote (phrase) VALUES ('«Компьютер позволяет делать больше ошибок и быстрее, чем любое другое изобретение в истории человечества.»');
INSERT INTO quote (phrase) VALUES ('«Моя жена сказала мне: "Или я, или твой дурацкий проект!" Боже, как я буду по ней скучать...»');
INSERT INTO quote (phrase) VALUES ('«В теории, теория и практика — это одно и то же. На практике — нет.» — Йоги Берра');
INSERT INTO quote (phrase) VALUES ('«Я настолько умен, что иногда не понимаю ни единого слова из того, что говорю.» — Оскар Уайльд');
INSERT INTO quote (phrase) VALUES ('«Самый лучший способ запомнить день рождения жены — забыть его хотя бы один раз.»');
INSERT INTO quote (phrase) VALUES ('«Я не толстый, я просто легче заметен.» — Чак Норрис');
INSERT INTO quote (phrase) VALUES ('«Я всегда хотел быть кем-то, но теперь я понимаю, что нужно было формулировать точнее.» — Лили Томлин');
INSERT INTO quote (phrase) VALUES ('«Возраст — это всего лишь число. И в моем случае, это число с опечаткой.»');
INSERT INTO quote (phrase) VALUES ('«Пессимист — это человек, который, когда перед ним ставят выбор из двух зол, выбирает оба.» — Оскар Уайльд');
INSERT INTO quote (phrase) VALUES ('«Счастье не в деньгах, а в их количестве... хотя кто-то утверждает, что главное — это покупки.»');
INSERT INTO quote (phrase) VALUES ('«Если сначала у вас ничего не получилось, значит, парашютный спорт — точно не для вас.» — Стивен Райт');
INSERT INTO quote (phrase) VALUES ('«Если факт не сходится с теорией, измените факт.» — Альберт Эйнштейн');
INSERT INTO quote (phrase) VALUES ('«Некоторые люди приносят счастье, куда бы они ни пошли; другие — откуда бы они ни ушли.» — Оскар Уайльд');
INSERT INTO quote (phrase) VALUES ('«Никогда не перебивай своего врага, когда он совершает ошибку.» — Наполеон Бонапарт');
INSERT INTO quote (phrase) VALUES ('«Теория — это когда все известно, но ничего не работает. Практика — это когда все работает, но никто не знает почему. Мы же объединяем теорию и практику: ничего не работает, и никто не знает почему.» — Альберт Эйнштейн');
INSERT INTO quote (phrase) VALUES ('«Постоянно откладывая дела на завтра, вы однажды обнаружите, что у вас осталось полно пустых вчера.» — Гарольд Хилл');
INSERT INTO quote (phrase) VALUES ('«Деньги не купят вам счастья, но с ними гораздо комфортнее плакать в Мерседесе, чем на велосипеде.»');
INSERT INTO quote (phrase) VALUES ('«Только 10 типов людей понимают двоичный код: те, кто понимают, и те, кто нет.»');
INSERT INTO quote (phrase) VALUES ('«Если вы думаете, что обучение обходится дорого, попробуйте невежество.» — Бенджамин Франклин');
INSERT INTO quote (phrase) VALUES ('«Всё, что вам нужно в этой жизни — это невежество и уверенность; тогда успех вам обеспечен.» — Марк Твен');
INSERT INTO quote (phrase) VALUES ('«Мой код не содержит багов. Это просто случайные незадокументированные фичи.»');
INSERT INTO quote (phrase) VALUES ('«Два ведра воды и ни капли смысла — вот рецепт моего успеха!»');
INSERT INTO quote (phrase) VALUES ('«Самое сложное в программировании — придумать имена переменным и инвалидация кэша.» — Фил Карлтон');
INSERT INTO quote (phrase) VALUES ('«Любовь бежит от тех, кто гонится за нею, а тем, кто прочь бежит, кидается на шею.» — Уильям Шекспир');
INSERT INTO quote (phrase) VALUES ('«Жизнь коротка, искусство долговечно.» — Гиппократ');
INSERT INTO quote (phrase) VALUES ('«Лучший способ предсказать будущее — создать его.» — Питер Друкер');
INSERT INTO quote (phrase) VALUES ('«Я мыслю, следовательно, я существую.» — Рене Декарт');
INSERT INTO quote (phrase) VALUES ('«Опыт — это то, что вы получаете, когда не получаете того, что хотели.» — Дэн Стэнфорд');
INSERT INTO quote (phrase) VALUES ('«Чем больше я узнаю людей, тем больше мне нравятся собаки.» — Генрих Гейне');
INSERT INTO quote (phrase) VALUES ('«Кто не работает, тот ест! Учись, студент!» — из к/ф «Операция «Ы»»');
INSERT INTO quote (phrase) VALUES ('«Никогда не ошибается тот, кто ничего не делает.» — Теодор Рузвельт');
INSERT INTO quote (phrase) VALUES ('«Даже путь в тысячу ли начинается с первого шага.» — Лао-цзы');
INSERT INTO quote (phrase) VALUES ('«Счастье — это когда тебя понимают.» — из к/ф «Доживём до понедельника»');
INSERT INTO quote (phrase) VALUES ('«Надо уметь закрывать скучную книгу, уходить с плохого кино и увольняться с плохой работы.»');
INSERT INTO quote (phrase) VALUES ('«Человек есть мера всех вещей.» — Протагор');
INSERT INTO quote (phrase) VALUES ('«Если тебе дадут линованную бумагу, пиши поперек.» — Хуан Рамон Хименес');
INSERT INTO quote (phrase) VALUES ('«Всё течет, всё меняется.» — Гераклит');
INSERT INTO quote (phrase) VALUES ('«Оптимист видит возможность в каждой опасности, пессимист видит опасность в каждой возможности.» — Уинстон Черчилль');
INSERT INTO quote (phrase) VALUES ('«Сон — это лучшее лекарство, но у него побочный эффект: можно проспать работу.»');
INSERT INTO quote (phrase) VALUES ('«Я не ленивый, я просто нахожусь в режиме энергосбережения.»');
INSERT INTO quote (phrase) VALUES ('«Жизнь — как велосипед: чтобы сохранить равновесие, приходится двигаться.» — Альберт Эйнштейн');
INSERT INTO quote (phrase) VALUES ('«Гораздо легче любить всех людей вообще, чем одного человека в частности.» — Лев Толстой');
INSERT INTO quote (phrase) VALUES ('«Чтобы дойти до цели, надо прежде всего идти.» — Оноре де Бальзак');
INSERT INTO quote (phrase) VALUES ('«Мудрость приходит с годами, но иногда годы приходят одни.» — Оскар Уайльд');
INSERT INTO quote (phrase) VALUES ('«Кто владеет информацией, тот владеет миром.» — Натан Ротшильд');
INSERT INTO quote (phrase) VALUES ('«Слово — серебро, молчание — золото.» — народная мудрость');
INSERT INTO quote (phrase) VALUES ('«Самое великое в жизни — это любовь. Но если нет любви, то можно и поесть.»');
INSERT INTO quote (phrase) VALUES ('«Я пришел, я увидел, я забыл, зачем пришел.»');
INSERT INTO quote (phrase) VALUES ('«Лучшее — враг хорошего.» — Вольтер');
INSERT INTO quote (phrase) VALUES ('«Гений — это один процент вдохновения и девяносто девять процентов пота.» — Томас Эдисон');
INSERT INTO quote (phrase) VALUES ('«Знание — сила.» — Фрэнсис Бэкон');
INSERT INTO quote (phrase) VALUES ('«Всё, что нас не убивает, делает нас сильнее.» — Фридрих Ницше');
INSERT INTO quote (phrase) VALUES ('«Быть или не быть — вот в чем вопрос.» — Уильям Шекспир');
INSERT INTO quote (phrase) VALUES ('«Не откладывай на завтра то, что можно съесть сегодня.»');
INSERT INTO quote (phrase) VALUES ('«Красота спасет мир.» — Федор Достоевский');
INSERT INTO quote (phrase) VALUES ('«Где мало слов, там вес они имеют.» — Уильям Шекспир');
INSERT INTO quote (phrase) VALUES ('«У меня нет никаких особенных талантов. Я просто страсть как любопытен.» — Альберт Эйнштейн');
INSERT INTO quote (phrase) VALUES ('«Порой мы ищем то, чего нет, и теряем то, что есть.»');
INSERT INTO quote (phrase) VALUES ('«День, когда вы ничего не узнали, — это потерянный день.»');
INSERT INTO quote (phrase) VALUES ('«Смех — это солнце, которое прогоняет зиму с лица человека.» — Виктор Гюго');
INSERT INTO quote (phrase) VALUES ('«Единственная настоящая ошибка — это та, из которой мы не извлекаем уроков.» — Генри Форд');
INSERT INTO quote (phrase) VALUES ('«Друзья познаются в беде, а враги — в радости.»');
INSERT INTO quote (phrase) VALUES ('«Не бойтесь расти медленно, бойтесь оставаться неизменными.» — китайская пословица');
INSERT INTO quote (phrase) VALUES ('«Ничто так не выдает человека, как то, над чем он смеется.» — Иоганн Вольфганг фон Гете');
INSERT INTO quote (phrase) VALUES ('«Мы — то, что мы постоянно делаем. Совершенство — это не действие, а привычка.» — Аристотель');
INSERT INTO quote (phrase) VALUES ('«Никто не спотыкается, лежа в постели.» — японская пословица');
INSERT INTO quote (phrase) VALUES ('«Все люди рождаются свободными и равными в своем достоинстве и правах.» — Всеобщая декларация прав человека');
INSERT INTO quote (phrase) VALUES ('«Никогда не жалей о том, что заставило тебя улыбнуться.» — Марк Твен');
INSERT INTO quote (phrase) VALUES ('«Единственный способ сделать выдающуюся работу — любить то, что ты делаешь.» — Стив Джобс');
INSERT INTO quote (phrase) VALUES ('«Чем умнее человек, тем легче он признает себя дураком.» — Альберт Эйнштейн');
INSERT INTO quote (phrase) VALUES ('«Удача — это то, что происходит, когда подготовка встречается с возможностью.» — Сенека');
INSERT INTO quote (phrase) VALUES ('«Если вы не можете объяснить это просто, значит, вы не понимаете этого достаточно хорошо.» — Альберт Эйнштейн');
INSERT INTO quote (phrase) VALUES ('«Жизнь измеряется не количеством сделанных вдохов, а моментами, когда от счастья захватывает дух.»');
INSERT INTO quote (phrase) VALUES ('«Время — это то, чего мы хотим больше всего, но используем хуже всего.» — Уильям Пенн');
INSERT INTO quote (phrase) VALUES ('«Никто не может заставить вас чувствовать себя неполноценным без вашего согласия.» — Элеонора Рузвельт');
INSERT INTO quote (phrase) VALUES ('«Мир принадлежит оптимистам, пессимисты — всего лишь зрители.» — Франсуа Гизо');
INSERT INTO quote (phrase) VALUES ('«В любом проекте самое важное — не забыть сделать бекап.»');
INSERT INTO quote (phrase) VALUES ('«Величайшая слава не в том, чтобы никогда не ошибаться, а в том, чтобы уметь подняться каждый раз, когда падаешь.» — Конфуций');
INSERT INTO quote (phrase) VALUES ('«Если проблема имеет решение, то волноваться незачем, если решения нет, то волноваться бессмысленно.» — Далай-лама');
INSERT INTO quote (phrase) VALUES ('«Компьютер — это самый логичный идиот в мире.»');
INSERT INTO quote (phrase) VALUES ('«Чтение для ума — то же, что упражнения для тела.» — Джозеф Аддисон');
INSERT INTO quote (phrase) VALUES ('«Истина где-то рядом, но обычно она скрыта под слоем легаси-кода.»');
INSERT INTO quote (phrase) VALUES ('«Чем меньше знаешь, тем крепче спишь... но тем меньше зарплата.»');
INSERT INTO quote (phrase) VALUES ('«Всё гениальное просто, и всё простое гениально.» — Йозеф Геббельс');
INSERT INTO quote (phrase) VALUES ('«Кто понял жизнь, тот больше не спешит.» — Омар Хайям');
INSERT INTO quote (phrase) VALUES ('«Каждый человек — творец своего счастья.» — Саллюстий');
INSERT INTO quote (phrase) VALUES ('«Если хочешь рассмешить Бога, расскажи ему о своих планах.» — Вуди Аллен');
INSERT INTO quote (phrase) VALUES ('«Мысль материальна. Особенно та, что записана в коммит.»');
INSERT INTO quote (phrase) VALUES ('«Улыбайтесь! Это заставляет людей ломать голову над тем, что у вас на уме.»');
INSERT INTO quote (phrase) VALUES ('«Работать нужно не 12 часов, а головой.» — Стив Джобс');
INSERT INTO quote (phrase) VALUES ('«Всякая стена — это дверь.» — Ральф Уолдо Эмерсон');
INSERT INTO quote (phrase) VALUES ('«Ты не можешь менять направление ветра, но ты можешь поднять паруса, чтобы достичь своей цели.» — Джим Рон');
INSERT INTO quote (phrase) VALUES ('«Будьте собой, все остальные роли уже заняты.» — Оскар Уайльд');
INSERT INTO quote (phrase) VALUES ('«Они говорили: "Используй фреймворк, это будет быстро". Прошло три года...»');
INSERT INTO quote (phrase) VALUES ('«Человек, который перенес гору, начал с того, что перетаскивал мелкие камешки.» — китайская пословица');
INSERT INTO quote (phrase) VALUES ('«Вчера — это история, завтра — это тайна, а сегодня — это подарок.»');
INSERT INTO quote (phrase) VALUES ('«Иногда шаг вперед есть результат пинка сзади.»');
INSERT INTO quote (phrase) VALUES ('«Всё будет правильно, на этом построен мир.» — Михаил Булгаков');
INSERT INTO quote (phrase) VALUES ('«Я могу сопротивляться всему, кроме искушения.» — Оскар Уайльд');
INSERT INTO quote (phrase) VALUES ('«Никогда не указывайте на ошибки, если не знаете, как их исправить.» — Джордж Вашингтон');
INSERT INTO quote (phrase) VALUES ('«Правда бывает только одна, а лжи — бесконечное множество.»');
INSERT INTO quote (phrase) VALUES ('«Свобода — это право говорить людям то, чего они не хотят слышать.» — Джордж Оруэлл');
INSERT INTO quote (phrase) VALUES ('«Воображение важнее знания.» — Альберт Эйнштейн');
INSERT INTO quote (phrase) VALUES ('«Дорогу осилит идущий.» — латинское изречение');
INSERT INTO quote (phrase) VALUES ('«Когда кажется, что весь мир настроен против тебя, помни, что самолёт взлетает против ветра!» — Генри Форд');
INSERT INTO quote (phrase) VALUES ('«Никто не замечает, когда я делаю всё правильно, но все видят, когда я ошибаюсь.»');
INSERT INTO quote (phrase) VALUES ('«Интернет не сделал нас умнее, он сделал нашу глупость более доступной.»');
INSERT INTO quote (phrase) VALUES ('«Нет ничего более постоянного, чем временный костыль в коде.»');
INSERT INTO quote (phrase) VALUES ('«Жизнь бьет ключом, и всё по голове.» — народный фольклор');
INSERT INTO quote (phrase) VALUES ('«Молчание — это текст, который легче всего перевести.» — Жюль Ромэн');
INSERT INTO quote (phrase) VALUES ('«Если всё идет по плану, значит, вы чего-то не заметили.»');
INSERT INTO quote (phrase) VALUES ('«Краткость — сестра таланта.» — Антон Чехов');
INSERT INTO quote (phrase) VALUES ('«Ваши самые недовольные клиенты — это ваш самый главный источник обучения.» — Билл Гейтс');
INSERT INTO quote (phrase) VALUES ('«Теория — это когда ты знаешь, как это должно работать, но оно не работает.»');
INSERT INTO quote (phrase) VALUES ('«Лучше быть уверенным в хорошем результате, чем надеяться на отличный.»');
INSERT INTO quote (phrase) VALUES ('«Программное обеспечение как энтропия: его трудно охватить, оно ничего не весит и подчиняется Второму закону термодинамики.»');
INSERT INTO quote (phrase) VALUES ('«Всегда пишите код так, будто сопровождать его будет склонный к насилию психопат, который знает, где вы живете.» — Мартин Голдинг');
INSERT INTO quote (phrase) VALUES ('«Язык дан человеку, чтобы скрывать свои мысли.» — Шарль Морис де Талейран');
INSERT INTO quote (phrase) VALUES ('«Мудрец ищет все в самом себе, глупец — в другом.» — Конфуций');
INSERT INTO quote (phrase) VALUES ('«Умные мысли приходят лишь тогда, когда все глупости уже сделаны.»');
INSERT INTO quote (phrase) VALUES ('«Конец — это чье-то начало.» — из к/ф «Матрица: Революция»');
